import { AxisScale } from '@visx/axis';
import React, { PropsWithChildren } from 'react';

import { AnnotationsDataProvider } from './AnnotationsDataProvider.js';
import { AnnotationsRendererProvider } from './AnnotationsRendererProvider.js';
import { AnnotationsStoreProvider } from './AnnotationsStoreProvider.js';
import { AnnotationsActionsContext } from '../contexts/AnnotationsActionsContext.js';
import { AnnotationsMarkersInteractionContext } from '../contexts/AnnotationsMarkersInteractionContext.js';
import { SelectionState } from '../types/state.js';
import { AnnotationsActionsTemplate } from '../types/tooltip.js';
import { TrackProps } from '../types/tracks.js';

interface AnnotationsProvidersProps extends PropsWithChildren {
  scale: AxisScale<number>;
  onAnnotationsMarkersInteraction:
    | ((event: Partial<SelectionState>) => void)
    | undefined;
  tracks: TrackProps[];
  showLabels?: boolean;
  annotationsActions?: AnnotationsActionsTemplate;
}

export const AnnotationsProviders = ({
  children,
  scale,
  tracks,
  showLabels,
  onAnnotationsMarkersInteraction,
  annotationsActions,
}: PropsWithChildren<AnnotationsProvidersProps>) => (
  <AnnotationsRendererProvider scale={scale} showLabels={showLabels}>
    <AnnotationsDataProvider tracks={tracks}>
      <AnnotationsMarkersInteractionContext.Provider
        value={{ onMarkersInteraction: onAnnotationsMarkersInteraction }}
      >
        <AnnotationsActionsContext.Provider
          value={{ actions: annotationsActions }}
        >
          <AnnotationsStoreProvider>{children}</AnnotationsStoreProvider>
        </AnnotationsActionsContext.Provider>
      </AnnotationsMarkersInteractionContext.Provider>
    </AnnotationsDataProvider>
  </AnnotationsRendererProvider>
);

AnnotationsProviders['displayName'] = 'AnnotationsProviders';
